from .exceptions import (CannotStartLSU, CannotStartTSTM, CannotStartEPC,
                         CannotStartS1, CannotAttach, CannotDetach)
import time
import logging


class PrismaComponents(object):
    def __init__(self, prisma, components_list):
        """

        :param prisma: taf.ue.prisma instance
        """
        self.__prisma = prisma
        self.__lsu_s1_node = "lsu_s1"
        self.__lsu_uu_node = "lsu_uu"
        self.__tstm_x2_node = "tstm_x2"
        self.__tstm_uu_node = "tstm_uu"
        self.__airmosaic_node = "airmosaic"
        self.__real_enb, self.__nokia_epcsim = self.__check_environment_type(components_list)

    def __check_environment_type(self, components_list):
        """
        If there is lsu s1 node, means environment using prisma simulate epc, require to init epc.
        Otherwise is using nokia epcsim, no need to init epc.

        :param components_list:
        :return:
        """
        real_enb = True
        nokia_epcsim = True
        if self.__lsu_s1_node in components_list:
            nokia_epcsim = False
        if self.__tstm_x2_node in components_list:
            real_enb = False
        return real_enb, nokia_epcsim

    def prepare_servers(self, sid, config_dir):
        logging.info("Try to stop nodes before prepare.")
        self._stop_servers()
        self._start_servers()
        if self.__nokia_epcsim:
            self.start_airmosaic_and_prepare_test(
                sid=sid,
                config_dir=config_dir,
            )
        else:
            self.start_s1_link_on_lsu_s1(
                sid=sid,
                config_dir=config_dir,
            )

    def _stop_servers(self):
        if not self.__nokia_epcsim:
            self.stop_lsu_s1()
        self.stop_lsu_uu()
        if not self.__real_enb:
            self.stop_tstm_x2()
        self.stop_tstm_uu()

    def _start_servers(self):
        if not self.__nokia_epcsim:
            self.start_lsu_s1()
        self.start_lsu_uu()
        if not self.__real_enb:
            self.start_tstm_x2()
        self.start_tstm_uu()

    def start_lsu_s1(self):
        response = self.__prisma.start_lsu(node_name=self.__lsu_s1_node)
        logging.debug("Starting lsu s1, result: {}".format(response))
        if "lsustart completed correctly" not in response[1]:
            raise CannotStartLSU(node_name=self.__lsu_s1_node)

    def stop_lsu_s1(self):
        try:
            self.__prisma.stop_lsu(node_name=self.__lsu_s1_node)
        except Exception as e:
            logging.warning("Failed to stop lsu s1 node: {}".format(e))

    def start_lsu_uu(self, timeout=120):
        response = self.__prisma.create_5g_cell(
            node_name=self.__lsu_uu_node, timeout=timeout
        )
        logging.debug("Starting lsu uu, result: {}".format(response))
        if "lsustart completed correctly" not in response[1]:
            raise CannotStartLSU(node_name=self.__lsu_uu_node)
        self.__check_5g_cell_id(node_name=self.__lsu_uu_node)

    def stop_lsu_uu(self, timeout=30):
        try:
            self.__prisma.stop_lsu(node_name=self.__lsu_uu_node, timeout=timeout)
        except Exception as e:
            logging.warning("Failed to stop lsu uu node: {}".format(e))

    def start_tstm_x2(self):
        self.__prisma.stop_tstm(node_name=self.__tstm_x2_node)
        self.__prisma.clean_tstm_log(node_name=self.__tstm_x2_node)
        self.__prisma.start_tstm(node_name=self.__tstm_x2_node)
        response = self.__prisma.get_tstm_log(
            node_name=self.__tstm_x2_node,
            expected_regex="SOKLISTEN",
            timeout=90,
        )
        logging.debug("Starting tstm x2, result: {}".format(response))
        if "SOKLISTEN" not in response[1]:
            raise CannotStartTSTM(node_name=self.__tstm_x2_node)

    def stop_tstm_x2(self):
        try:
            self.__prisma.stop_tstm(node_name=self.__tstm_x2_node)
        except Exception as e:
            logging.warning("Failed to stop tstm x2 node: {}".format(e))

    def start_tstm_uu(self):
        self.__prisma.clean_tstm_log(node_name=self.__tstm_uu_node)
        logging.debug("Cleaned tstm log.")
        self.__prisma.start_tstm(node_name=self.__tstm_uu_node)
        response = self.__prisma.get_tstm_log(
            node_name=self.__tstm_uu_node,
            expected_regex="SOKLISTEN",
            timeout=90
        )
        logging.debug("Starting tstm uu, result: {}".format(response))
        if "SOKLISTEN" not in response[1]:
            raise CannotStartTSTM(node_name=self.__tstm_uu_node)

    def stop_tstm_uu(self):
        try:
            self.__prisma.stop_tstm(node_name=self.__tstm_uu_node)
        except Exception as e:
            logging.warning("Failed to stop tstm uu node: {}".format(e))

    def start_s1_link_on_lsu_s1(self, sid, config_dir):
        self.__prisma.stop_epc(node_name=self.__lsu_s1_node)
        self.__prisma.clean_epc_log(node_name=self.__lsu_s1_node)
        self.__prisma.start_epc(node_name=self.__lsu_s1_node)
        # add 1 min sleep to ensure all epc log printed.
        response = self.__prisma.get_epc_log(
            node_name=self.__lsu_s1_node,
            expected_regex=r"MultiSchedule\.tsm Started, Waiting for UDP Client Request",
            timeout=90
        )
        logging.debug("Starting epc, result: {}".format(response))
        if "MultiSchedule.tsm Started, Waiting for UDP Client Request" not in response[1]:
            raise CannotStartEPC(node_name=self.__lsu_s1_node)
        self.__init_epc()
        self.start_airmosaic_and_prepare_test(
            sid=sid,
            config_dir=config_dir
        )
        response2 = self.__prisma.get_epc_log(
            node_name=self.__lsu_s1_node,
            expected_regex="S1 Setup Successful",
            timeout=90
        )
        logging.debug("Starting S1 link, result: {}".format(response2))
        if "S1 Setup Successful" not in response2[1]:
            raise CannotStartS1(node_name=self.__lsu_s1_node)

    def __init_epc(self):
        response = self.__prisma.init_epc(node_name=self.__lsu_s1_node)
        logging.debug("Initializing epc, result: {}".format(response))
        # if "Received from Tstm: OK" not in response[1]:
        #     raise CannotInitEPC(node_name=self.__lsu_s1_node)

    def start_airmosaic_and_prepare_test(self, sid, config_dir):
        resp = self.__prisma.close_mosaic()
        logging.debug("Close Airmosaic, result: {}".format(resp))
        response = self.__prisma.start_mosaic()
        logging.info("Airmosaic start result:{}.".format(response))
        time.sleep(60)
        self.__prisma.prepare_test(
            sid=sid,
            config_dir=config_dir,
            timeout=60
        )
        logging.info("Prepare test finished.")

    def stop_s1_link_on_lsu_s1(self):
        self.__prisma.close_mosaic()
        time.sleep(10)

    def stop_running_test(self):
        self.__prisma.stop_test_running()
        time.sleep(5)
        self.__prisma.clear_test()
        time.sleep(2)

    def attach(self, wait_for_complete=False, timeout=120):
        logging.info("Starting attach.")
        logging.debug("Before attach status: {}".format(self.__prisma.get_scenario_status()))
        self.__prisma.ue_attach(
            node_name=self.__airmosaic_node,
            wait_for_complete=wait_for_complete,
            timeout=timeout
        )
        self._check_execute_finished()
        logging.debug("Attach finished, checking result.")
        attach_log = self.__check_attach_to_enb(node_name=self.__airmosaic_node)
        self.__check_random_access(node_name=self.__airmosaic_node)
        return attach_log

    def __check_attach_to_enb(self, node_name, retry=3):
        logging.info("Checking attach to eNB.")
        for _ in range(retry):
            logging.debug("Current status:{}".format(self.__prisma.get_scenario_status()))
            if self.__nokia_epcsim:
                response = self.__prisma.get_scenario_logger(
                    node_name=node_name
                )
                logging.debug("Attaching to eNB, result: {}".format(response))
                if "UE Attached" in str(response):
                    break
            else:
                response = self.__prisma.get_epc_log(
                    node_name=self.__lsu_s1_node,
                    expected_regex="ATTACH SUCCESSFUL"
                )
                if "ATTACH SUCCESSFUL" in str(response):
                    break
            logging.info("Couldn't get attached massage, retry in 10s.")
            time.sleep(10)
        else:
            raise CannotAttach(node_name=node_name)
        logging.info("Attach to eNB succeed.")
        return response

    def __check_random_access(self, node_name):
        logging.info("Checking Random access.")
        response = self.__prisma.get_ra_status(node_name=self.__lsu_uu_node)
        logging.debug("Random access result: {}".format(response))
        if "RA_SuccessCompletion" not in response[1]:
            raise CannotAttach(node_name=node_name)
        logging.info("Random access valid.")

    def detach(self, wait_for_complete=False, timeout=120):
        self.__prisma.ue_detach(
            node_name=self.__airmosaic_node,
            wait_for_complete=wait_for_complete,
            timeout=timeout)
        self._check_execute_finished()
        logging.info("Detach finished, checking result.")
        self.__check_detach_enb()

    def __check_detach_enb(self, retry=3):
        for _ in range(retry):
            if not self.__nokia_epcsim:
                response = self.__prisma.get_epc_log(
                    node_name=self.__lsu_s1_node,
                    expected_regex="DETACH SUCCESSFUL"
                )
                logging.debug("Detaching result: {}".format(response))
                if "DETACH SUCCESSFUL" in str(response):
                    break
            else:
                response = self.__prisma.get_scenario_logger()
                logging.debug("Detaching result: {}".format(response))
                if "UE Detached" in str(response):
                    break
            time.sleep(30)
        else:
            raise CannotDetach(node_name=self.__airmosaic_node)
        # logging.warning("Real enb environment don't have way to check detach result yet.")
        logging.info("Detached.")

    def __check_5g_cell_id(self, node_name, retry=3):
        for _ in range(retry):
            time.sleep(60)
            try:
                response = self.__prisma.get_5g_cell_id(node_name=node_name)
            except Exception as e:
                logging.warning(e)
                break
            logging.debug("Checking 5g cell id, result: {}".format(response))
            if "MASTER LOCKED" in str(response):
                logging.info("Check 5g cell succeed.")
                break
            logging.info("Check 5g cell id failed, try again in 60s.")
        else:
            logging.warning("Check 5g cell id failed!")

    def _check_execute_finished(self):
        logging.info("Getting scenario to confirm execute finished.")
        check_count = 0
        while True:
            scenario = self.__prisma.get_scenario_status()
            if scenario == "SCENARIO_COMPLETED":
                logging.info("SCENARIO_COMPLETED")
                break
            elif scenario == "SCENARIO_AVAILABLE":
                logging.warning("Airmosaic turn into SCENARIO_AVAILABLE, not SCENARIO_COMPLETED.")
                break
            check_count += 1
            logging.info("{}, check again in 30s. Check times = {}".format(scenario, check_count))
            time.sleep(30)
